// Independent semantic expectations, not snapshots of generated engine output.
import {baseline,scenario,defect,portfolio,complete,reorder,healthy} from './builders.mjs';
import {consumer} from '../action-plan/builders.mjs';
import {scenario as annuity} from '../debt-capacity/builders.mjs';
import {riskInputs} from '../recommendations/builders.mjs';
export function buildExplainabilityEntries(){const cases=[];const add=(description,input,expectations)=>cases.push({caseId:'EXP-RU-'+String(cases.length+1).padStart(3,'0'),description,synthetic:true,reviewStatus:'GOLDEN',input,expectations});const risk=(code,extra={},expectations={},values=riskInputs[code])=>add(code,scenario({values,...extra}),{required:[code],...expectations});
add('Complete canonical-consumer profile',healthy(),{status:'GENERATED'});
add('Partial assessment',baseline(),{status:'PARTIAL'});
add('Insufficient core data',baseline({missingCore:true}),{status:'INSUFFICIENT_DATA'});
for(const code of ['RISK-LEGAL-ENTITY-TERMINATED','RISK-LEGAL-LIQUIDATION-ACTIVE','RISK-LEGAL-BANKRUPTCY-ACTIVE'])risk(code,{}, {status:'NOT_RATABLE_GLOBAL_STOP'});
add('No material negative findings',healthy(),{noInventedFindings:true,noCreditRisk:true});
risk('RISK-DATA-SOURCE-MISSING',{}, {dataQuality:true});
risk('RISK-FIN-EQUITY-NON-POSITIVE',{}, {binding:['FIN_EQUITY',-100]});
risk('RISK-FIN-EQUITY-NON-POSITIVE',{}, {binding:['FIN_EQUITY',0],text:['RISK-FIN-EQUITY-NON-POSITIVE','равны нулю']},{FIN_EQUITY:0});
risk('RISK-FIN-NET-ASSETS-NEGATIVE',{}, {text:['RISK-FIN-NET-ASSETS-NEGATIVE','отчетное']});
risk('RISK-FIN-NET-ASSETS-PROXY-NEGATIVE',{}, {text:['RISK-FIN-NET-ASSETS-PROXY-NEGATIVE','прокси']});
for(const code of ['RISK-FIN-CURRENT-LIQUIDITY','RISK-FIN-WORKING-CAPITAL','RISK-FIN-NET-LOSS-CURRENT','RISK-FIN-NET-LOSS-REPEATED','RISK-FIN-REVENUE-DECLINE','RISK-FIN-INTEREST-COVERAGE'])risk(code);
risk('RISK-CF-DEBT-SERVICE-BURDEN',{}, {severity:['RISK-CF-DEBT-SERVICE-BURDEN','MEDIUM']},{BANK_DEBT_SERVICE_RATIO:.3,BANK_COVERAGE_ADEQUATE:true});
risk('RISK-CF-DEBT-SERVICE-BURDEN',{}, {severity:['RISK-CF-DEBT-SERVICE-BURDEN','HIGH']});
risk('RISK-CF-OPERATING-RECEIPTS-DECLINE');risk('RISK-CF-CUSTOMER-CONCENTRATION');
risk('RISK-CF-CUSTOMER-CONCENTRATION',{contract:true},{required:['RISK-CF-CUSTOMER-CONCENTRATION','CONTEXT:EXPLAINS']});
add('Marketplace context',scenario({marketplace:true}),{contextCopy:true});
for(const code of ['RISK-CF-LIQUIDITY-STRESS','RISK-DATA-UNKNOWN-INFLOW-SHARE','RISK-DATA-CASH-INDIVIDUAL-TRACEABILITY','RISK-DATA-BALANCE-RECONSTRUCTION'])risk(code);
risk('RISK-BKI-CURRENT-OVERDUE',{}, {},{BKI_OVERDUE:1000,BKI_HISTORY_DAYS:30});
risk('RISK-BKI-CURRENT-OVERDUE',{lowFinding:'RISK-BKI-CURRENT-OVERDUE'},{confidence:['RISK-BKI-CURRENT-OVERDUE','LOW'],text:['RISK-BKI-CURRENT-OVERDUE','требуется подтверждение']});
risk('RISK-BKI-HISTORICAL-DELINQUENCY',{}, {forbidden:['RISK-BKI-CURRENT-OVERDUE']});
add('Overdue with historical zero',defect(),{defect:true});
for(const code of ['RISK-DATA-PORTFOLIO-OBLIGATION-UNRESOLVED','RISK-DATA-PORTFOLIO-OUTSTANDING-UNKNOWN','RISK-DATA-PORTFOLIO-CONFLICT','RISK-DATA-UNSPLIT-DEBT-SERVICE'])risk(code);
add('Guarantee contingent exposure',baseline({creditPortfolio:portfolio({type:'BANK_GUARANTEE'})}),{portfolioSeparation:true});
add('Guarantorship not funded principal',baseline({creditPortfolio:portfolio({type:'GUARANTORSHIP',payment:0})}),{portfolioSeparation:true});
for(const code of ['RISK-DATA-SOURCE-MISSING','RISK-DATA-SOURCE-STALE','RISK-DATA-SOURCE-FAILED','RISK-DATA-BANK-COVERAGE'])risk(code);
add('Partial bank coverage',scenario({monthCount:6}),{status:'PARTIAL'});
risk('RISK-DATA-BANK-COVERAGE',{}, {},{BANK_COVERAGE_ISSUE:3});
for(const code of ['RISK-DATA-COMPANY-IDENTITY-CONFLICT','RISK-DATA-FINANCIAL-SAME-FACT-CONFLICT','RISK-DATA-SOURCE-INTEGRITY'])risk(code);
add('Four index components',baseline(),{components:4});
risk('RISK-CF-DEBT-SERVICE-BURDEN',{}, {debtRouting:true});
add('Context modifier copied once',scenario({contract:true,values:riskInputs['RISK-CF-CUSTOMER-CONCENTRATION']}),{driverCopy:true});
add('No invented modifier',scenario({values:{FIN_EQUITY:-100}}),{driverCopy:true});
for(const [v,level]of [[900,'HIGH'],[700,'MEDIUM'],[400,'LOW']])add(level+' readiness',baseline({indexValue:v}),{binding:['level',level]});
add('Partial readiness',baseline({monthCount:6}),{readinessCopy:true});
add('Uncertainty cap does not reduce points',scenario({values:{SOURCE_STALE_COUNT:1}}),{readinessCopy:true});
add('Positive headroom',baseline({indexValue:900}),{binding:['HEADROOM_prudential',200000]});
add('Zero headroom',scenario({debt:1000000}),{binding:['HEADROOM_prudential',0],text:['CAPACITY','не выявлен']});
add('Partial capacity',baseline({monthCount:6}),{text:['CAPACITY','частичный расчет']});
add('Insufficient capacity',baseline({monthCount:2}),{status:'INSUFFICIENT_DATA',binding:['HEADROOM_prudential',null]});
add('Recurring versus near-term anchor',baseline({creditPortfolio:portfolio({payment:300000})}),{required:['CAPACITY:recurringView','CAPACITY:nearTerm30dView'],capacityCopy:true});
add('Recent decline conservative operating basis',healthy({operating:[...Array(9).fill(1000000),...Array(3).fill(400000)]}),{capacityCopy:true,conservativeDecline:true});
add('Explicit annuity',baseline({scenarios:[annuity()]}),{required:['CAPACITY_SCENARIO'],text:['CAPACITY_SCENARIO','эквивалент в рамках заданного сценария']});
add('No scenario no principal equivalent',baseline(),{forbidden:['CAPACITY_SCENARIO']});
add('Requested amount above capacity not refusal',baseline({amount:100000000,scenarios:[annuity()]}),{text:['CAPACITY_SCENARIO','не является отказом банка']});
for(const [description,opts,code]of [['Working capital',{purpose:'WORKING_CAPITAL'},'CREDIT_LINE'],['Liquidity gap',{purpose:'LIQUIDITY_GAP'},'OVERDRAFT'],['Contract guarantee',{purpose:'CONTRACT_EXECUTION',contract:true},'BANK_GUARANTEE'],['Factoring',{factoring:true},'FACTORING'],['Equipment',{purpose:'EQUIPMENT'},'LEASING']])add(description,baseline(opts),{required:['PRODUCT:'+code],productCopy:true});
add('Aligned requested product',baseline({purpose:'WORKING_CAPITAL',requested:'CREDIT_LINE'}),{productCopy:true});
add('Misaligned requested product',baseline({purpose:'EQUIPMENT',requested:'OVERDRAFT'}),{text:['REQUESTED_PRODUCT_ALIGNMENT','не является основным']});
add('Zero headroom constrains fit',baseline({debt:1000000}),{productCopy:true});
add('Fit is not approval',baseline(),{text:['PRODUCT:CREDIT_LINE','не означает одобрение']});
add('Recommendation cause',scenario({values:{FIN_EQUITY:-100}}),{recommendationCopy:true});
add('Recommendation copy',baseline(),{recommendationCopy:true});
for(const [h,spec]of [['DAY_7',{priority:'P1_HIGH',effort:'LOW'}],['DAY_30',{remediability:'DIRECT'}],['DAY_60',{effort:'HIGH'}]])add(h+' checkpoint',complete(consumer([spec])),{required:['PLAN:'+h]});
add('Checkpoint not deadline',baseline(),{text:['HORIZON:DAY_7','не юридический срок']});
for(const [code,trigger]of [['VERIFY_CURRENT_OVERDUE_BALANCE','UPDATED_BKI'],['UPLOAD_COMPLETE_BANK_STATEMENT_PERIOD','NEW_BANK_STATEMENT_PERIOD'],['EXPLAIN_CURRENT_LOSS','UPDATED_FINANCIAL_STATEMENTS']])add(trigger,complete(consumer([{definitionCode:code}])),{required:['RERUN:'+trigger]});
add('No forced day7 rerun',complete(consumer([{effort:'HIGH'}])),{noForcedRerun:true});
add('Completion not resolution',complete(consumer([{actionability:'VERIFY_FIRST'}])),{text:['HORIZON:DAY_7','не означает устранение']});
risk('RISK-BKI-CURRENT-OVERDUE',{lowFinding:'RISK-BKI-CURRENT-OVERDUE'},{confidence:['RISK-BKI-CURRENT-OVERDUE','LOW']});
add('Client declaration label',baseline(),{clientDeclared:true});
add('No invented rejection reason',baseline(),{noPromises:true});
add('No approval or growth promise',baseline(),{noPromises:true});
add('Unordered set invariance',reorder(baseline()),{deterministicReorder:true});
cases.push({caseId:'EXP-RU-DEFECT-001',description:'Permanent overdue/KNOWN-zero-history chain',synthetic:true,reviewStatus:'GOLDEN',input:defect(),expectations:{defect:true,required:['RISK-BKI-CURRENT-OVERDUE'],forbidden:['RISK-BKI-HISTORICAL-DELINQUENCY']}});return cases;}
